/**
 * Provider-agnostic pieces of the SMTP quick setup.
 *
 * Every email provider we can set up in one click (Resend today, Mailgun and
 * SendGrid next) follows the same shape: authorize through a console OAuth2
 * provider, list the sending domains, mint a sending-only credential, then
 * write it into the project's custom SMTP settings. This module holds the
 * parts of that flow that do not depend on which provider is used.
 *
 * Safe to import from both the browser and the `_api` server routes.
 */

/**
 * Provider access tokens are short lived (Resend issues 15 minutes). Anything
 * expiring inside this window counts as expired so a request never races the
 * expiry.
 */
export const PROVIDER_TOKEN_EXPIRY_SKEW_MS = 60_000

export function isProviderTokenExpired(
  expiry: string | null | undefined,
  now: number = Date.now(),
  skewMs: number = PROVIDER_TOKEN_EXPIRY_SKEW_MS,
): boolean {
  if (!expiry) return true
  const timestamp = Date.parse(expiry)
  if (Number.isNaN(timestamp)) return true
  return timestamp - skewMs <= now
}

// ---------------------------------------------------------------------------
// OAuth2 round trip
// ---------------------------------------------------------------------------

/** Query param carrying the outcome of the round trip. */
export const QUICK_SETUP_STATUS_PARAM = 'smtpSetup'
/** Query param carrying which provider was authorized. */
export const QUICK_SETUP_PROVIDER_PARAM = 'smtpProvider'

export type QuickSetupReturn =
  | { status: 'connected'; providerId: string }
  | { status: 'failed'; providerId: string; message?: string }

function asNonEmptyString(value: unknown): string | undefined {
  if (typeof value === 'string') return value.trim() || undefined
  // TanStack Router JSON-parses search values, so an all-digit id arrives as a number.
  if (typeof value === 'number' && Number.isFinite(value)) return String(value)
  return undefined
}

/** Appwrite appends `error` as a JSON string `{ message, type, code }` to the failure URL. */
export function parseOAuthErrorMessage(error: unknown): string | undefined {
  const raw = asNonEmptyString(error)
  if (!raw) return undefined
  try {
    const parsed = JSON.parse(raw) as { message?: unknown }
    if (
      parsed &&
      typeof parsed === 'object' &&
      typeof parsed.message === 'string'
    ) {
      return parsed.message.trim() || undefined
    }
  } catch {
    // Not JSON, use the raw value.
  }
  return raw
}

/**
 * Success and failure URLs handed to Appwrite. Both point back at the page the
 * flow starts from: the token flow keeps the caller's console session, so the
 * provider can return straight to a guarded console route.
 *
 * Appwrite appends `error` on failure, and `userId` + `secret` on success. The
 * quick setup ignores that one-time token, because the same round trip writes a
 * fresh provider access token onto the account's identity, which is what the
 * flow reads. `stripQuickSetupReturn` drops it from the URL on arrival.
 */
export function buildQuickSetupOAuthUrls(
  /** Absolute URL of the page to come back to. */
  returnUrl: string,
  providerId: string,
): { success: string; failure: string } {
  const separator = returnUrl.includes('?') ? '&' : '?'
  const provider = `${QUICK_SETUP_PROVIDER_PARAM}=${encodeURIComponent(providerId)}`
  return {
    success: `${returnUrl}${separator}${QUICK_SETUP_STATUS_PARAM}=connected&${provider}`,
    failure: `${returnUrl}${separator}${QUICK_SETUP_STATUS_PARAM}=failed&${provider}`,
  }
}

/**
 * Read the outcome from the page's search params. Returns `null` when the page
 * was not reached through a quick setup round trip.
 */
export function parseQuickSetupReturn(
  search: unknown,
): QuickSetupReturn | null {
  if (!search || typeof search !== 'object') return null
  const params = search as Record<string, unknown>
  const status = params[QUICK_SETUP_STATUS_PARAM]
  const providerId = asNonEmptyString(params[QUICK_SETUP_PROVIDER_PARAM])

  if (!providerId) return null
  if (status === 'connected') return { status: 'connected', providerId }
  if (status === 'failed') {
    return {
      status: 'failed',
      providerId,
      message: parseOAuthErrorMessage(params.error),
    }
  }
  return null
}

/** Drop every param the round trip adds; keeps unrelated search state. */
export function stripQuickSetupReturn(prev: unknown): Record<string, unknown> {
  const next: Record<string, unknown> =
    prev && typeof prev === 'object'
      ? { ...(prev as Record<string, unknown>) }
      : {}
  delete next[QUICK_SETUP_STATUS_PARAM]
  delete next[QUICK_SETUP_PROVIDER_PARAM]
  delete next.error
  // Appwrite's token flow also appends a one-time login token that the quick
  // setup never uses. Drop it so it does not linger in the address bar, the
  // history entry, or a referrer header.
  delete next.userId
  delete next.secret
  return next
}

// ---------------------------------------------------------------------------
// Sending domains and credentials
// ---------------------------------------------------------------------------

/**
 * A sending domain, normalized across providers. Each adapter maps its own
 * shape onto this (Resend `status: 'verified'`, Mailgun `state: 'active'`,
 * SendGrid `valid: true`).
 */
export interface QuickSetupDomain {
  id: string
  name: string
  verified: boolean
}

/** Verified domains first, then alphabetical, so the default pick is usable. */
export function sortQuickSetupDomains<T extends QuickSetupDomain>(
  domains: T[],
): T[] {
  return [...domains].sort((a, b) => {
    const verifiedDelta = Number(b.verified) - Number(a.verified)
    if (verifiedDelta !== 0) return verifiedDelta
    return a.name.localeCompare(b.name)
  })
}

export const DEFAULT_SENDER_LOCAL_PART = 'noreply'

export function defaultSenderEmail(domainName: string): string {
  return `${DEFAULT_SENDER_LOCAL_PART}@${domainName}`
}

export function emailBelongsToDomain(email: string, domainName: string) {
  const trimmed = email.trim()
  const at = trimmed.lastIndexOf('@')
  if (at <= 0 || at === trimmed.length - 1) return false
  return trimmed.slice(at + 1).toLowerCase() === domainName.trim().toLowerCase()
}

/**
 * Prefer the domain the project already sends from; otherwise the first
 * verified domain. Returns `undefined` when nothing is verified.
 */
export function pickDefaultQuickSetupDomain<T extends QuickSetupDomain>(
  domains: T[],
  currentSenderEmail: string | null | undefined,
): T | undefined {
  const verified = domains.filter((domain) => domain.verified)
  if (currentSenderEmail) {
    const match = verified.find((domain) =>
      emailBelongsToDomain(currentSenderEmail, domain.name),
    )
    if (match) return match
  }
  return verified[0]
}

/**
 * Feature ID stored in the account's `featureNotifications` pref when a user
 * registers interest in a provider that is still coming soon. Must stay free
 * of commas, since that pref is a comma-separated list.
 */
export function providerInterestFeatureId(providerId: string): string {
  return `smtp-quick-setup-${providerId}`
}

/**
 * One minted credential that nothing depends on yet, so it can be revoked
 * instead of piling up at the provider when the flow does not get to use it.
 */
export interface MintedCredentialTracker<
  T extends { id: string; secret: string },
> {
  /** Start tracking a fresh credential; the previous unused one is revoked. */
  track(credential: T): void
  /**
   * A save that stores `secret` on success is in flight. The matching
   * credential is off limits until it settles: on success it is in use for
   * good, on failure it is revocable again (or revoked right away when the
   * flow was released or the key replaced in the meantime). A save that does
   * not carry the minted secret changes nothing: the user replaced the key by
   * hand, so the minted one stays revocable.
   */
  settle(secret: unknown, save: Promise<unknown>): void
  /**
   * The flow is over (abandoned, failed, unmounted): revoke whatever is still
   * unused. A credential whose save is still in flight is decided by that
   * save instead, so closing the flow mid-save cannot revoke a key that ends
   * up stored.
   */
  release(): void
}

/**
 * Shared by every surface that mints credentials, so the rules live in one
 * place: revoke only while the credential is unused, never while a save is
 * deciding it, and mint again only after revoking the previous unused one.
 *
 * `revoke` is best effort. Its failures are swallowed, because the caller has
 * already moved on from the credential and there is nothing left to retry.
 */
export function createMintedCredentialTracker<
  T extends { id: string; secret: string },
>(revoke: (credentialId: string) => Promise<void>): MintedCredentialTracker<T> {
  /** Minted and unused, so revocable. */
  let minted: T | null = null
  /** Handed to a save that has not settled yet. */
  let saving: T | null = null
  let released = false
  const revokeQuietly = (credential: T) => {
    void revoke(credential.id).catch(() => {})
  }
  return {
    track(credential) {
      const previous = minted
      minted = credential
      if (previous) revokeQuietly(previous)
    },
    settle(secret, save) {
      if (!minted || minted.secret !== secret) return
      const credential = minted
      minted = null
      saving = credential
      save.then(
        () => {
          if (saving === credential) saving = null
        },
        () => {
          if (saving !== credential) return
          saving = null
          // Back to unused for a retry, unless the flow is gone or a newer
          // credential took its place in the meantime.
          if (released || minted) revokeQuietly(credential)
          else minted = credential
        },
      )
    },
    release() {
      released = true
      const current = minted
      minted = null
      if (current) revokeQuietly(current)
    },
  }
}

/** Credential name written at the provider, trimmed to that provider's limit. */
export function buildCredentialName(
  projectName: string,
  maxLength: number,
): string {
  const prefix = 'Appwrite SMTP'
  const trimmed = projectName.trim()
  const name = trimmed ? `${prefix}: ${trimmed}` : prefix
  if (name.length <= maxLength) return name
  return name.slice(0, maxLength).trimEnd()
}
/**
 * Resend specifics for the SMTP quick setup. Everything provider-agnostic
 * lives in `quick-setup.ts`; the registry entry is in `providers.ts`.
 *
 * Safe to import from both the browser and the `_api` server routes.
 */

/**
 * Resend only issues `emails:send` and `full_access`. Appwrite's adapter asks
 * for `emails:send` by default; creating API keys and listing domains needs
 * `full_access`, so it is requested explicitly on top.
 */
export const RESEND_OAUTH_SCOPES = ['full_access']

/** SMTP relay settings documented at https://resend.com/docs/send-with-smtp */
export const RESEND_SMTP_HOST = 'smtp.resend.com'
export const RESEND_SMTP_PORT = 587
export const RESEND_SMTP_USERNAME = 'resend'
export const RESEND_SMTP_SECURE = 'tls' as const

export const RESEND_DOMAINS_URL = 'https://resend.com/domains'
export const RESEND_CREDENTIAL_NAME_MAX_LENGTH = 50

/**
 * Sanitized body for `POST /api-keys`. The server relay rebuilds the payload
 * from this so it can only ever mint sending-only keys.
 */
export interface CreateResendApiKeyBody {
  name: string
  permission: 'sending_access'
  domain_id?: string
}

export function sanitizeCreateApiKeyBody(
  input: unknown,
): CreateResendApiKeyBody | null {
  if (!input || typeof input !== 'object') return null
  const record = input as Record<string, unknown>
  const name = typeof record.name === 'string' ? record.name.trim() : ''
  if (!name || name.length > RESEND_CREDENTIAL_NAME_MAX_LENGTH) return null

  const body: CreateResendApiKeyBody = { name, permission: 'sending_access' }
  const domainId = record.domain_id ?? record.domainId
  if (typeof domainId === 'string' && domainId.trim()) {
    body.domain_id = domainId.trim()
  }
  return body
}
/**
 * Resend REST adapter for the SMTP quick setup (browser side).
 *
 * `api.resend.com` sends no CORS headers, so requests go through the console's
 * own `_api/resend/*` server routes (see `resend-proxy.ts`), which forward the
 * bearer token verbatim and never persist it.
 */

import type { QuickSetupDomain } from './quick-setup'
import type { SmtpQuickSetupCredential } from './providers'

/** Mount point of the `src/routes/_api/resend/*` server routes. */
export const RESEND_PROXY_BASE_PATH = '/resend'

export class ResendApiError extends Error {
  status: number
  code?: string

  constructor(message: string, status: number, code?: string) {
    super(message)
    this.name = 'ResendApiError'
    this.status = status
    this.code = code
  }
}

export function isResendUnauthorizedError(error: unknown): boolean {
  return error instanceof ResendApiError && error.status === 401
}

type ResendErrorPayload = {
  message?: unknown
  name?: unknown
  statusCode?: unknown
}

function readErrorPayload(payload: unknown): {
  message?: string
  code?: string
} {
  if (!payload || typeof payload !== 'object') return {}
  const record = payload as ResendErrorPayload
  return {
    message:
      typeof record.message === 'string' && record.message.trim()
        ? record.message
        : undefined,
    code: typeof record.name === 'string' ? record.name : undefined,
  }
}

async function resendFetch<T>(
  path: string,
  accessToken: string,
  init: RequestInit = {},
): Promise<T> {
  const headers = new Headers(init.headers)
  headers.set('Accept', 'application/json')
  headers.set('Authorization', `Bearer ${accessToken}`)
  if (init.body !== undefined && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json')
  }

  const response = await fetch(`${RESEND_PROXY_BASE_PATH}${path}`, {
    ...init,
    headers,
    credentials: 'same-origin',
    cache: 'no-store',
  })

  const text = await response.text()
  let payload: unknown = null
  if (text) {
    try {
      payload = JSON.parse(text)
    } catch {
      payload = null
    }
  }

  if (!response.ok) {
    const { message, code } = readErrorPayload(payload)
    throw new ResendApiError(
      message ?? `Resend request failed (${response.status})`,
      response.status,
      code,
    )
  }

  return payload as T
}

type ResendDomainResponse = {
  id?: unknown
  name?: unknown
  status?: unknown
}

function normalizeDomain(raw: ResendDomainResponse): QuickSetupDomain | null {
  if (typeof raw.id !== 'string' || typeof raw.name !== 'string') return null
  return {
    id: raw.id,
    name: raw.name,
    verified: raw.status === 'verified',
  }
}

const DOMAINS_PAGE_SIZE = 100
const DOMAINS_MAX_PAGES = 10

/** Every domain on the connected Resend account (verified or not). */
export async function listResendDomains(
  accessToken: string,
): Promise<QuickSetupDomain[]> {
  const domains: QuickSetupDomain[] = []
  let after: string | undefined

  for (let page = 0; page < DOMAINS_MAX_PAGES; page++) {
    const params = new URLSearchParams({ limit: String(DOMAINS_PAGE_SIZE) })
    if (after) params.set('after', after)

    const result = await resendFetch<{
      data?: ResendDomainResponse[]
      has_more?: boolean
    }>(`/domains?${params.toString()}`, accessToken)

    const chunk = (result?.data ?? [])
      .map(normalizeDomain)
      .filter((domain): domain is QuickSetupDomain => domain !== null)
    domains.push(...chunk)

    if (!result?.has_more || chunk.length === 0) break
    after = chunk[chunk.length - 1]!.id
  }

  return domains
}

/** Mint a sending-only API key, optionally restricted to one domain. */
export async function createResendCredential(
  accessToken: string,
  input: { name: string; domainId?: string },
): Promise<SmtpQuickSetupCredential> {
  const result = await resendFetch<{ id?: unknown; token?: unknown }>(
    '/api-keys',
    accessToken,
    {
      method: 'POST',
      body: JSON.stringify({
        name: input.name,
        permission: 'sending_access',
        ...(input.domainId ? { domain_id: input.domainId } : {}),
      }),
    },
  )

  if (typeof result?.id !== 'string' || typeof result?.token !== 'string') {
    throw new ResendApiError('Resend did not return an API key', 502)
  }
  return { id: result.id, secret: result.token }
}

/** Best-effort cleanup when a freshly minted key could not be saved to the project. */
export async function deleteResendCredential(
  accessToken: string,
  credentialId: string,
): Promise<void> {
  await resendFetch<unknown>(
    `/api-keys/${encodeURIComponent(credentialId)}`,
    accessToken,
    { method: 'DELETE' },
  )
}
/**
 * Registry of email providers offered by the SMTP quick setup card.
 *
 * Adding a provider is meant to be one entry here plus an API adapter:
 * fill in the SMTP relay settings, point at the console OAuth2 provider that
 * issues an access token for it, and implement {@link SmtpQuickSetupApi}.
 * Entries without `oauth` + `api` render as "Coming soon".
 */

import { OAuthProvider } from '@appwrite.io/console'
import type { AnalyticsActionId } from '@/lib/analytics-actions'
import {
  RESEND_CREDENTIAL_NAME_MAX_LENGTH,
  RESEND_DOMAINS_URL,
  RESEND_OAUTH_SCOPES,
  RESEND_SMTP_HOST,
  RESEND_SMTP_PORT,
  RESEND_SMTP_SECURE,
  RESEND_SMTP_USERNAME,
} from './resend'
import {
  createResendCredential,
  deleteResendCredential,
  isResendUnauthorizedError,
  listResendDomains,
} from './resend-api'
import type { QuickSetupDomain } from './quick-setup'

export type SmtpQuickSetupProviderId = 'resend' | 'mailgun' | 'sendgrid'

/** A sending credential minted at the provider; `secret` becomes the SMTP password. */
export interface SmtpQuickSetupCredential {
  id: string
  secret: string
}

/** Provider REST calls the setup dialog needs, each taking a provider access token. */
export interface SmtpQuickSetupApi {
  listDomains(accessToken: string): Promise<QuickSetupDomain[]>
  createCredential(
    accessToken: string,
    input: { name: string; domainId?: string },
  ): Promise<SmtpQuickSetupCredential>
  /** Best-effort cleanup when a minted credential could not be saved. */
  deleteCredential(accessToken: string, credentialId: string): Promise<void>
  /** True when the provider rejected the access token (triggers one refresh + retry). */
  isUnauthorizedError(error: unknown): boolean
}

export interface SmtpQuickSetupProvider {
  id: SmtpQuickSetupProviderId
  name: string
  /** Asset under `/public/icons`. */
  iconPath: string
  /** One line shown next to the provider name. */
  tagline: string
  /**
   * Connect button label and wizard titles. Whole sentences per provider
   * rather than fragments joined with the brand, so languages that order
   * words differently still read correctly.
   */
  connectLabel: string
  setupTitle: string
  disconnectTitle: string
  smtp: {
    host: string
    port: number
    secure: 'tls' | 'ssl'
    /** Mailgun uses `postmaster@<domain>`, so this resolves per selected domain. */
    username: (domainName: string) => string
  }
  /** Where the user manages sending domains at the provider. */
  domainsUrl: string
  credentialNameMaxLength: number
  analyticsAction: AnalyticsActionId
  /** Console OAuth2 provider that issues an access token for this provider. */
  oauth?: { provider: OAuthProvider; scopes: string[] }
  api?: SmtpQuickSetupApi
}

/** Provider entry that the flow can actually run end to end. */
export type AvailableSmtpQuickSetupProvider = SmtpQuickSetupProvider &
  Required<Pick<SmtpQuickSetupProvider, 'oauth' | 'api'>>

export const SMTP_QUICK_SETUP_PROVIDERS: readonly SmtpQuickSetupProvider[] = [
  {
    id: 'resend',
    name: 'Resend',
    iconPath: '/icons/resend.svg',
    tagline: 'Creates a sending-only API key for a verified domain.',
    connectLabel: 'Connect with Resend',
    setupTitle: 'Set up SMTP with Resend',
    disconnectTitle: 'Disconnect Resend',
    smtp: {
      host: RESEND_SMTP_HOST,
      port: RESEND_SMTP_PORT,
      secure: RESEND_SMTP_SECURE,
      username: () => RESEND_SMTP_USERNAME,
    },
    domainsUrl: RESEND_DOMAINS_URL,
    credentialNameMaxLength: RESEND_CREDENTIAL_NAME_MAX_LENGTH,
    analyticsAction: 'smtp-quick-setup-resend',
    oauth: { provider: OAuthProvider.Resend, scopes: RESEND_OAUTH_SCOPES },
    api: {
      listDomains: listResendDomains,
      createCredential: createResendCredential,
      deleteCredential: deleteResendCredential,
      isUnauthorizedError: isResendUnauthorizedError,
    },
  },
  {
    id: 'mailgun',
    name: 'Mailgun',
    iconPath: '/icons/mailgun.svg',
    tagline: 'Creates a domain sending key for a verified domain.',
    connectLabel: 'Connect with Mailgun',
    setupTitle: 'Set up SMTP with Mailgun',
    disconnectTitle: 'Disconnect Mailgun',
    smtp: {
      host: 'smtp.mailgun.org',
      port: 587,
      secure: 'tls',
      username: (domainName) => `postmaster@${domainName}`,
    },
    domainsUrl: 'https://app.mailgun.com/mg/sending/domains',
    credentialNameMaxLength: 64,
    analyticsAction: 'smtp-quick-setup-mailgun',
    // No console OAuth2 provider for Mailgun yet, so this stays "Coming soon".
  },
  {
    id: 'sendgrid',
    name: 'SendGrid',
    iconPath: '/icons/sendgrid.svg',
    tagline: 'Creates a restricted API key with mail send access.',
    connectLabel: 'Connect with SendGrid',
    setupTitle: 'Set up SMTP with SendGrid',
    disconnectTitle: 'Disconnect SendGrid',
    smtp: {
      host: 'smtp.sendgrid.net',
      port: 587,
      secure: 'tls',
      username: () => 'apikey',
    },
    domainsUrl: 'https://app.sendgrid.com/settings/sender_auth',
    credentialNameMaxLength: 100,
    analyticsAction: 'smtp-quick-setup-sendgrid',
    // No console OAuth2 provider for SendGrid yet, so this stays "Coming soon".
  },
]

/** True when the provider has both an OAuth2 provider and an API adapter wired. */
export function isProviderAvailable(
  provider: SmtpQuickSetupProvider,
): provider is AvailableSmtpQuickSetupProvider {
  return Boolean(provider.oauth && provider.api)
}

export function getSmtpQuickSetupProvider(
  providerId: string | null | undefined,
): SmtpQuickSetupProvider | undefined {
  if (!providerId) return undefined
  return SMTP_QUICK_SETUP_PROVIDERS.find(
    (provider) => provider.id === providerId,
  )
}

/** Provider ready to run the flow, or `undefined` (unknown id or coming soon). */
export function getAvailableSmtpQuickSetupProvider(
  providerId: string | null | undefined,
): AvailableSmtpQuickSetupProvider | undefined {
  const provider = getSmtpQuickSetupProvider(providerId)
  return provider && isProviderAvailable(provider) ? provider : undefined
}
/**
 * Appwrite side of the SMTP quick setup: authorize an email provider through
 * the console OAuth2 token flow and read the provider access token it leaves
 * behind.
 *
 * Token lifecycle (browser only):
 * 1. `startProviderAuthorization` redirects through `account.createOAuth2Token`
 *    and back to the page it was called from. That flow keeps the caller's
 *    console session (appwrite/appwrite#13602), so the provider can return
 *    straight to a guarded console route.
 * 2. Appwrite links the provider account to the signed-in user and writes a
 *    fresh provider access token onto that identity.
 * 3. `resolveProviderAccessToken` reads it back. Providers issue short-lived
 *    tokens (Resend 15 minutes), which covers the setup that follows; once one
 *    expires the user authorizes again.
 *
 * Refreshing is deliberately not wired up. Appwrite can only refresh a
 * *session's* provider token (`account.updateSession`), so holding on to a
 * refresh token would mean minting a provider-flavored console session on every
 * connect. Re-authorizing costs one silent redirect instead, and the account's
 * session list keeps describing console sessions.
 *
 * Nothing here is provider-specific beyond the id and scopes passed in, so the
 * same flow serves every entry in `providers.ts`.
 */

import { Query, type Models } from '@appwrite.io/console'
import { sdk } from '@/lib/appwrite/sdk'
import { buildQuickSetupOAuthUrls, isProviderTokenExpired } from './quick-setup'
import type { AvailableSmtpQuickSetupProvider } from './providers'

export interface ProviderAccessToken {
  token: string
  /** ISO 8601 expiry reported by Appwrite. */
  expiry: string
}

/** No usable provider token for this account; only a new OAuth2 flow can help. */
export class QuickSetupReauthorizeRequiredError extends Error {
  constructor(
    message = 'Provider authorization is required',
    options?: ErrorOptions,
  ) {
    super(message, options)
    this.name = 'QuickSetupReauthorizeRequiredError'
  }
}

/**
 * The identity Appwrite linked for this provider. Its presence is what
 * "this account is connected" means, so deleting it disconnects the provider.
 */
export async function findProviderIdentity(
  providerId: string,
): Promise<Models.Identity | null> {
  const response = await sdk.forConsole.account.listIdentities({
    queries: [Query.equal('provider', [providerId]), Query.limit(1)],
    total: false,
  })
  return response.identities?.[0] ?? null
}

/**
 * Provider access token for this account, or `null` when only a new
 * authorization can help: either the account is not connected, or the token
 * the last round trip left on the identity has expired.
 */
export async function resolveProviderAccessToken(
  providerId: string,
): Promise<ProviderAccessToken | null> {
  const identity = await findProviderIdentity(providerId)
  if (!identity?.providerAccessToken) return null
  if (isProviderTokenExpired(identity.providerAccessTokenExpiry)) return null
  return {
    token: identity.providerAccessToken,
    expiry: identity.providerAccessTokenExpiry,
  }
}

/**
 * Leave for the provider's consent screen and come back to the current page
 * with the outcome in its search params. The console session survives the round
 * trip, so the page is reached as the signed-in user; only its in-memory state
 * is lost to the navigation.
 *
 * The return URL keeps the path and drops any existing search params, so a
 * stale outcome from an earlier attempt cannot ride along.
 */
export function startProviderAuthorization(
  provider: AvailableSmtpQuickSetupProvider,
): void {
  if (typeof window === 'undefined') {
    throw new Error('Provider authorization requires a browser')
  }
  const { success, failure } = buildQuickSetupOAuthUrls(
    `${window.location.origin}${window.location.pathname}`,
    provider.id,
  )
  const result = sdk.forConsole.account.createOAuth2Token({
    provider: provider.oauth.provider,
    success,
    failure,
    scopes: provider.oauth.scopes,
  })
  // In browsers the SDK navigates itself; outside of one it returns the URL.
  if (typeof result === 'string') {
    window.location.assign(result)
  }
}
import { useCallback, useRef } from 'react'
import { isProviderTokenExpired } from './quick-setup'
import {
  QuickSetupReauthorizeRequiredError,
  resolveProviderAccessToken,
  type ProviderAccessToken,
} from './quick-setup-oauth'
import type { AvailableSmtpQuickSetupProvider } from './providers'

/**
 * Holds provider access tokens for the current page and runs API calls with
 * them. Tokens live in a ref only: nothing is persisted, and a reload reads
 * them back from the account's identities.
 *
 * Shared by every surface that talks to an email provider on the user's behalf
 * (project SMTP settings, the messaging provider wizard), so the reconnect
 * rules stay in one place.
 */
export function useProviderTokens() {
  const tokensRef = useRef(new Map<string, ProviderAccessToken>())

  /**
   * Runs a provider API call with a live token, reading one off the account's
   * identity when nothing usable is cached. There is no refresh path: a token
   * the provider rejects needs a new authorization just like a missing or
   * expired one, so both raise {@link QuickSetupReauthorizeRequiredError} for
   * the caller to offer a reconnect.
   */
  const callWith = useCallback(
    async <T>(
      provider: AvailableSmtpQuickSetupProvider,
      run: (accessToken: string) => Promise<T>,
    ): Promise<T> => {
      let current = tokensRef.current.get(provider.id)
      if (!current || isProviderTokenExpired(current.expiry)) {
        const resolved = await resolveProviderAccessToken(provider.id)
        if (!resolved) throw new QuickSetupReauthorizeRequiredError()
        current = resolved
        tokensRef.current.set(provider.id, current)
      }
      try {
        return await run(current.token)
      } catch (error) {
        if (!provider.api.isUnauthorizedError(error)) throw error
        tokensRef.current.delete(provider.id)
        throw new QuickSetupReauthorizeRequiredError(undefined, {
          cause: error,
        })
      }
    },
    [],
  )

  /** Caches a token for the provider. False means a new authorization is due. */
  const prime = useCallback(
    async (provider: AvailableSmtpQuickSetupProvider) => {
      const token = await resolveProviderAccessToken(provider.id)
      if (!token) return false
      tokensRef.current.set(provider.id, token)
      return true
    },
    [],
  )

  /** Drops a cached token, e.g. after the identity behind it was deleted. */
  const forget = useCallback((providerId: string) => {
    tokensRef.current.delete(providerId)
  }, [])

  return { callWith, prime, forget }
}
